<?php
/**
 * Maliit na pop-up bago mag-print o mag-PDF ng report (Admin/Staff):
 *   Generated by - kusang pangalan ng naka-login na user (hindi na binabago)
 *   From         - kanino/saang opisina galing ang papel, o para saan ito
 * Gamit sa JavaScript:
 *   spAskExportPeople('Pangalan').then(function (p) { if (p) { p.by; p.from; } });
 * Ibinabalik ang null kapag kinansela.
 */
?>
<div class="xp-backdrop" id="xpDialog" role="dialog" aria-modal="true" aria-labelledby="xpTitle" hidden>
    <form class="xp-card" id="xpForm" novalidate>
        <h3 id="xpTitle"><i class="fa-solid fa-file-pdf"></i> Report details</h3>
        <p>These appear on the printed report.</p>
        <label for="xpFrom">From</label>
        <input type="text" id="xpFrom" maxlength="150" placeholder="e.g., City Veterinary Office - Records Section">
        <small class="xp-err" id="xpErr" hidden>Please fill in "From".</small>
        <div class="xp-actions">
            <button type="button" class="xp-cancel" id="xpCancel">Cancel</button>
            <button type="submit" class="xp-ok"><i class="fa-solid fa-check"></i> Continue</button>
        </div>
    </form>
</div>
<style>
    .xp-backdrop { position: fixed; inset: 0; z-index: 10040; display: flex; align-items: center; justify-content: center; padding: 16px; background: rgba(15, 23, 20, .5); backdrop-filter: blur(4px); }
    .xp-backdrop[hidden] { display: none; }
    .xp-card { width: 100%; max-width: 420px; background: #fff; border-radius: 16px; padding: 20px 22px; display: flex; flex-direction: column; gap: 6px; box-shadow: 0 24px 60px rgba(0, 0, 0, .3); font-family: inherit; }
    .xp-card h3 { margin: 0; font-size: 17px; color: #1b4332; display: flex; align-items: center; gap: 8px; }
    .xp-card h3 i { color: #c0392b; }
    .xp-card p { margin: 0 0 6px; font-size: 13px; color: #6b7280; }
    .xp-card label { font-size: 12.5px; font-weight: 700; color: #374151; margin-top: 6px; }
    .xp-card input { height: 40px; padding: 0 12px; border: 1px solid #d1d5db; border-radius: 10px; font-family: inherit; font-size: 14px; }
    .xp-card input:focus { outline: none; border-color: #2d6a4f; box-shadow: 0 0 0 3px rgba(45, 106, 79, .15); }
    .xp-card input.is-missing { border-color: #dc2626; }
    .xp-err { color: #dc2626; font-size: 12.5px; font-weight: 600; }
    .xp-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 12px; }
    .xp-cancel, .xp-ok { height: 40px; padding: 0 16px; border-radius: 10px; font-family: inherit; font-weight: 700; font-size: 13.5px; cursor: pointer; }
    .xp-cancel { border: 1px solid #d1d5db; background: #fff; color: #374151; }
    .xp-ok { border: none; background: #1b4332; color: #fff; display: inline-flex; align-items: center; gap: 6px; }
    @media (max-width: 600px) { .xp-card input { font-size: 16px; } }
</style>
<script>
(function () {
    const dlg = document.getElementById('xpDialog');
    const from = document.getElementById('xpFrom'), err = document.getElementById('xpErr');
    let done = null, by = '';
    function close(result) {
        dlg.hidden = true;
        if (done) { const d = done; done = null; d(result); }
    }
    window.spAskExportPeople = function (defaultBy) {
        by = defaultBy || '';
        from.classList.remove('is-missing');
        err.hidden = true;
        dlg.hidden = false;
        setTimeout(function () { from.focus(); }, 30);
        return new Promise(function (resolve) { done = resolve; });
    };
    document.getElementById('xpForm').addEventListener('submit', function (e) {
        e.preventDefault();
        if (from.value.trim() === '') { from.classList.add('is-missing'); err.hidden = false; from.focus(); return; }
        close({ by: by, from: from.value.trim() });
    });
    document.getElementById('xpCancel').addEventListener('click', function () { close(null); });
    dlg.addEventListener('click', function (e) { if (e.target === dlg) close(null); });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && !dlg.hidden) close(null); });
})();
</script>
